# Generated by scripts/release/activate-bootstrap.mjs. DO NOT HAND-EDIT.
# quantum-activate: turns a Quantum Memory activation code into a licence, then installs
# quantum-agent-os with it. Licence-free download; Homebrew checks the sha256 below.
class QuantumActivate < Formula
  desc "Activate Quantum Memory with a code, then install it"
  homepage "https://quantummemory.ai"
  url "https://github.com/KingJackWins/homebrew-quantum-memory/releases/download/quantum-activate-v0.5.27/quantum-activate-0.5.27-5c033c82eaa2.tar.gz"
  sha256 "5c033c82eaa2ae075b20c0db58f4c052394b938d256e23601739d8df346cee95"
  version "0.5.27"
  license :cannot_represent

  depends_on arch: :arm64
  depends_on "node"

  def install
    libexec.install Dir["*"]
    (bin/"quantum-activate").write <<~SH
      #!/bin/sh
      exec /usr/bin/env -i HOME="$HOME" USER="$USER" LOGNAME="$LOGNAME" TERM="${TERM:-dumb}" LANG=en_US.UTF-8 PATH=/usr/bin:/bin:/usr/sbin:/sbin ${QAOS_HOME+"QAOS_HOME=$QAOS_HOME"} "#{Formula["node"].opt_bin}/node" "#{libexec}/quantum-activate.mjs" --brew-prefix "#{HOMEBREW_PREFIX}" "$@"
    SH
    chmod 0755, bin/"quantum-activate"
  end

  def caveats
    <<~EOS
      Run quantum-activate and type the activation code Jack sent you.
      It stays hidden as you type, then Quantum Memory installs.
    EOS
  end

  test do
    assert_match "quantum-activate", shell_output("#{bin}/quantum-activate --help 2>&1", 0)
  end
end
